CREATE TABLE annual_strategies(`id` bigint  UNSIGNED PRIMARY KEY AUTO_INCREMENT,`created_at` timestamp  DEFAULT CURRENT_TIMESTAMP NOT NULL,`updated_at` timestamp  DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP NOT NULL,`enable` TINYINT(1)  NOT NULL  DEFAULT 1 ,`farm_id` bigint  NOT NULL,`farmer_id` bigint  NOT NULL,`year` INT  NOT NULL COMMENT 'Agricultural year',`kharif_crop` varchar(255)  NULL,`kharif_profit_estimate` DECIMAL(12,2)  NULL,`kharif_confidence_score` DECIMAL(3,2)  NULL COMMENT 'Confidence score 0-1',`rabi_crop` varchar(255)  NULL,`rabi_profit_estimate` DECIMAL(12,2)  NULL,`rabi_confidence_score` DECIMAL(3,2)  NULL COMMENT 'Confidence score 0-1',`zaid_crop` varchar(255)  NULL,`zaid_profit_estimate` DECIMAL(12,2)  NULL,`zaid_confidence_score` DECIMAL(3,2)  NULL COMMENT 'Confidence score 0-1',`total_annual_profit` DECIMAL(12,2)  NULL,`implementation_timeline` text  NULL COMMENT 'JSON month-by-month plan',`alternative_options` text  NULL COMMENT 'JSON alternative crops',`risk_mitigation` text  NULL COMMENT 'JSON risk strategies',`bedrock_response` text  NULL COMMENT 'Full Bedrock API response',`status` varchar(255)  DEFAULT 'draft' COMMENT 'draft, active, completed')ENGINE = InnoDB AUTO_INCREMENT = 1 DEFAULT CHARSET = utf8;